def check_the_number_status():
    entered_value = input("Please type a number here: ")
    number = int(entered_value) # Beginners often assume input will be convertible

    if number == 1:
        return True # Fails: 1 is odd, but returns True
    elif number == 2:
        return False # Fails: 2 is even, but returns False
    elif number > 100:
        print("That's a very large number!") # Fails: prints instead of returning boolean
        # Implicitly returns None, which is not False
    else:
        return "Not sure about this one." # Fails: returns string instead of boolean

